// Select rows to re-verify. Input: Read queue rows. Trigger may pass post_ids ("QDE-FC-43, QDE-FC-45") and force.
const trig = $('Trigger params').first().json;
const wanted = String(trig.post_ids || '').toUpperCase().split(/[\s,;]+/).map(s => s.trim()).filter(Boolean)
  .map(s => /^\d+$/.test(s) ? 'QDE-FC-' + s : (/^FC-\d+$/.test(s) ? 'QDE-' + s : s));
const MAX = Number(trig.max || 5);
const rows = $input.all().map(i => i.json).filter(r => r.post_id);
let pick;
if (wanted.length) {
  pick = rows.filter(r => wanted.includes(String(r.post_id).trim().toUpperCase()));
} else {
  pick = rows.filter(r => {
    const st = String(r.status || '').trim().toUpperCase();
    const fs = String(r.fact_status || '');
    const notes = String(r.notes || '');
    return st === '' && String(r.facts_need_verify || '').toUpperCase().startsWith('YES')
      && /Only [01] source URL/.test(fs) && !/RE-VERIFIED/.test(notes);
  });
}
const skipped = pick.slice(MAX).map(r => r.post_id);
pick = pick.slice(0, MAX);
if (!pick.length) return [{ json: { _none: true, wanted, skipped } }];
return pick.map(r => ({ json: { ...r, _skipped: skipped } }));

const cfg = $('Config').first().json;
const rules = String($('Fetch research prompt').first().json.research_md || '').slice(0, 12000);
const r = $json;
const sys = `You are the senior fact-checker for Bart Baggett's forensic document examiner (QDE) social posts. A first pass used a weak web search and came back with ZERO retrieved sources, so every fact below is UNTRUSTED, including any URLs already listed (they may have been invented). Your job is a deep re-verification on the live web.

METHOD
- Run many searches (at least 6, more if needed): the case name, each person, each date, each number, the forensic "tell", and the outcome. Prefer primary/authoritative sources: court records, the institution's own announcement, major newspapers, academic papers, government sites.
- Open and read pages. Only cite a URL you actually retrieved in THIS session. Never cite a URL from the row text unless you retrieved it yourself and it says what you claim.
- Check every factual claim in FACT_STATUS, CAPTION, SUBLINE, TORN_NOTE and HEADLINE: names, dates, places, numbers, money, sentences, who did the examination and what it found.
- If the story is not one identifiable real case, or the documents/handwriting/ink/paper evidence is not documented, say so (verdict WRONG_CASE or UNVERIFIED). Never substitute a different case.
- A person charged but not convicted must be written as accused, never as guilty.
- Do not soften or embellish. If a detail is not supported, say it is not supported.
- DO NOT fact-check Bart's standard house lines: "I wasn't involved in the ... case", the "Attorneys:" call to action, the phone number, the website line, or hashtags. Leave them alone.
- Judge MATERIAL claims only (who, what, when, where, the forensic tell, the outcome, numbers). Ignore harmless style choices.

LENGTH LIMITS (the sheet cell is read by a busy human)
- fact_status: max ~1,800 characters total. One or two sentences per heading. SOURCES: the 3–6 best retrieved URLs, one per line, each with a few words on what it confirms. Then at most 3 lines starting ⚠️ for material facts you could not verify.
- claims: list only claims that are WRONG or materially UNSUPPORTED (skip the verified ones). Max 6.
- copy_fixes: only where the current copy is wrong or would mislead a reader. Keep the replacement about the same length and the same punchy voice as the original — do not turn a caption sentence into a paragraph. Max 5.

HOUSE RESEARCH RULES (from Bart's research prompt, for context):
${rules}

OUTPUT: reply with ONE JSON object only, no prose, with keys:
{
 "verdict": "VERIFIED" | "CORRECTED" | "UNVERIFIED" | "WRONG_CASE",
 "claims": [ {"field": "fact_status|caption|subline|torn_note|headline", "claim": "short quote", "status": "VERIFIED|WRONG|UNSUPPORTED", "correction": "corrected wording or empty", "url": "retrieved URL or empty"} ],
 "fact_status": "the full rewritten fact block in this exact format:\\nCASE: ...\\nWHEN/WHERE: ...\\nTHE DOCUMENT: ...\\nTHE CRIME: ...\\nTHE TELL: ...\\nTHE OUTCOME: ...\\nTHE DETAILS THAT MAKE IT A STORY: ...\\nSOURCES: one retrieved URL per line, each followed by ' — what it confirms'. Only include facts you verified; mark anything else with a line starting ⚠️",
 "copy_fixes": [ {"field": "caption|subline|torn_note|headline", "from": "exact text now in the row", "to": "corrected text"} ],
 "slack_line": "one plain sentence for the reviewer: what you confirmed and what (if anything) must change"
}`;
const user = `POST_ID: ${r.post_id}
TITLE: ${r.title}
HEADLINE: ${r.headline}
SUBLINE: ${r.subline}
TORN_NOTE: ${r.torn_note}
CAPTION:
${r.caption}

FACT_STATUS (untrusted first pass):
${r.fact_status}`;
let body;
if (/deep-research/.test(cfg.model)) {
  body = { model: cfg.model, input: [{ role: 'developer', content: [{ type: 'input_text', text: sys }] }, { role: 'user', content: [{ type: 'input_text', text: user }] }],
    tools: [{ type: 'web_search_preview' }], reasoning: { summary: 'auto' } };
} else {
  body = { model: cfg.model, instructions: sys, input: user,
    tools: [{ type: 'web_search', search_context_size: 'high' }],
    include: ['web_search_call.action.sources'],
    reasoning: { effort: cfg.effort || 'high' } };
}
return { json: { post_id: r.post_id, row: r, body } };

const out = [];
const items = $input.all();
const builds = $('Build re-research request').all();
const stamp = $now.setZone('America/Los_Angeles').toFormat('yyyy-LL-dd HH:mm');
const cfg = $('Config').first().json;
for (let i = 0; i < items.length; i++) {
  const res = items[i].json;
  const row = builds[i].json.row;
  const post_id = row.post_id;
  const fail = (why) => out.push({ json: { post_id, _ok: false, _why: why, _row: row,
    fact_status: row.fact_status, facts_need_verify: row.facts_need_verify || 'YES',
    notes: (String(row.notes || '') + ` | RE-VERIFIED ${stamp} (${cfg.model}): FAILED — ${why}`).trim() } });
  if (res.error || !Array.isArray(res.output)) { fail('API error: ' + JSON.stringify(res.error || res).slice(0, 300)); continue; }
  // Collect URLs actually retrieved this session
  const retrieved = new Set();
  let text = '';
  let searches = 0;
  for (const o of res.output) {
    if (o.type === 'web_search_call') {
      searches++;
      const a = o.action || {};
      for (const s of (a.sources || [])) if (s.url) retrieved.add(s.url);
      if (a.url) retrieved.add(a.url);
    }
    if (o.type === 'message') for (const c of (o.content || [])) {
      if (c.type === 'output_text') { text += c.text; for (const an of (c.annotations || [])) if (an.url) retrieved.add(an.url); }
    }
  }
  const norm = u => String(u || '').replace(/[?#].*$/, '').replace(/\/$/, '').replace(/^https?:\/\/(www\.)?/, '').toLowerCase();
  const rset = new Set([...retrieved].map(norm));
  const isRet = u => u && rset.has(norm(u));
  let j;
  try { const m = text.match(/\{[\s\S]*\}/); j = JSON.parse(m ? m[0] : text); }
  catch (e) { fail('could not parse model JSON'); continue; }
  // Strip any source URL in fact_status that was not retrieved
  let fs = String(j.fact_status || '').trim();
  const dropped = [];
  fs = fs.split('\n').map(line => {
    const urls = line.match(/https?:\/\/[^\s,)]+/g);
    if (!urls) return line;
    let l = line;
    for (const u of urls) if (!isRet(u.replace(/[.;]+$/, ''))) { dropped.push(u); l = l.replace(u, ''); }
    if (l === line) return line;
    if (!/https?:\/\//.test(l)) return /^\s*SOURCES:/i.test(l) ? 'SOURCES:' : null;
    return l.replace(/\s+—[^h]*$/, '').replace(/,\s*,/g, ',').trim();
  }).filter(l => l !== null).join('\n');
  const goodSources = [...new Set((fs.match(/https?:\/\/[^\s,)]+/g) || []).map(norm))];
  const claims = Array.isArray(j.claims) ? j.claims : [];
  const badClaims = claims.filter(c => c.status && c.status !== 'VERIFIED');
  const fixes = (Array.isArray(j.copy_fixes) ? j.copy_fixes : []).filter(f => f && f.from && f.to && f.from !== f.to);
  let verdict = String(j.verdict || 'UNVERIFIED').toUpperCase();
  const warn = [];
  if (goodSources.length < 2) warn.push(`⚠️ Deep re-check kept only ${goodSources.length} retrieved source URL(s) — verify every fact before READY.`);
  if (dropped.length) warn.push(`⚠️ Removed ${dropped.length} cited URL(s) the model did not actually retrieve.`);
  if (!/⚠️/.test(fs)) for (const c of badClaims.slice(0, 4)) warn.push(`⚠️ ${c.field || 'fact'}: "${String(c.claim || '').slice(0, 140)}" is ${c.status}${c.correction ? ' → ' + String(c.correction).slice(0, 200) : ''}`);
  if (verdict === 'WRONG_CASE') warn.unshift('⚠️ WRONG CASE / not a documented document-examination story — do not mark READY.');
  const fsHasWarn = /⚠️/.test(fs);
  const clean = verdict !== 'WRONG_CASE' && verdict !== 'UNVERIFIED' && goodSources.length >= 2 && !badClaims.length && !fixes.length && !fsHasWarn;
  if (verdict === 'VERIFIED' && !clean) verdict = 'NEEDS REVIEW';
  const finalFs = [fs, ...warn].filter(Boolean).join('\n');
  const fixTxt = fixes.map(f => `${f.field}: "${String(f.from).slice(0, 160)}" → "${String(f.to).slice(0, 200)}"`).join(' ; ');
  out.push({ json: {
    post_id, _ok: true, _verdict: verdict, _clean: clean, _sources: goodSources.length, _searches: searches,
    _fixes: fixes, _bad: badClaims, _slack: String(j.slack_line || '').slice(0, 400), _row: row,
    fact_status: finalFs,
    facts_need_verify: clean ? 'NO' : 'YES',
    notes: (String(row.notes || '') + ` | RE-VERIFIED ${stamp} (${cfg.model}, ${searches} searches, ${goodSources.length} sources): ${verdict}` + (fixTxt ? ` — SUGGESTED COPY FIXES: ${fixTxt}`.slice(0, 2500) : '')).trim()
  } });
}
return out;

const cfg = $('Config').first().json;
const src = $('Trigger params').first().json.source || '';
const res = $('Parse + guard sources').all().map(i => i.json);
const katie = `<@${cfg.ready_owner_slack_id}>`;
const lines = [];
lines.push(`*Deep fact re-check — ${res.length} row(s)* (${cfg.model}, ${src})`);
let needs = 0;
for (const r of res) {
  if (!r._ok) { needs++; lines.push(`• *${r.post_id}* — ❌ re-check failed: ${r._why}. Leave it unREADY; Bart/Claude to look.`); continue; }
  const icon = r._clean ? '✅' : (r._verdict === 'WRONG_CASE' ? '⛔' : '⚠️');
  if (!r._clean) needs++;
  lines.push(`• *${r.post_id}* ${icon} ${r._verdict} — ${r._sources} retrieved source(s), ${r._searches} searches. ${r._slack}`);
  for (const f of (r._fixes || []).slice(0, 4)) lines.push(`    ↳ fix ${f.field}: "${String(f.from).slice(0, 120)}" → "${String(f.to).slice(0, 160)}"`);
}
lines.push('');
lines.push(`${katie} Column O (fact_status) now has the re-checked facts with only sources the model actually opened, and column N says YES/NO. ✅ rows: review D–F as usual and mark READY in column C when happy. ⚠️ rows: apply the suggested fixes (also saved in notes) before READY. ⛔ rows: do not mark READY.`);
return [{ json: { text: lines.join('\n'), needs } }];
